using Rhino; using System.Text.Json; using System.IO;
namespace RhinoContextAssist;
internal sealed class ContextAssistSettings {
 readonly PersistentSettings store; public bool Enabled{get;set;} public bool AutomaticPrioritization{get;set;} public int PrimaryCount{get;set;} public PopupUxMode UxMode{get;set;} public PopupPositionMode PositionMode{get;set;} public int SelectionDelayMs{get;set;} public int HoverDelayMs{get;set;} public int CollapseDelayMs{get;set;} public int MoreCollapseDelayMs{get;set;} public int AutoHideMs{get;set;} public int CursorOffsetPx{get;set;} public int IdleOpacity{get;set;} public int ActiveOpacity{get;set;} public int CornerMarginPx{get;set;} public List<ContextAction> CustomActions{get;}=new(); public Dictionary<SelectionKind,List<ActionPreference>> Preferences{get;}=new(); public Dictionary<string,UsageEntry> Usage{get;}=new();
 public ContextAssistSettings(PersistentSettings s){store=s;Load();}
 void Load(){Enabled=store.GetBool("Enabled",true);AutomaticPrioritization=store.GetBool("Auto",true);PrimaryCount=Math.Clamp(store.GetInteger("Primary",5),1,5);UxMode=store.GetEnumValue("Ux",PopupUxMode.Compact);PositionMode=store.GetEnumValue("Position",PopupPositionMode.AutoViewportCorner);SelectionDelayMs=store.GetInteger("SelectionDelay",300);HoverDelayMs=store.GetInteger("HoverDelay",300);CollapseDelayMs=store.GetInteger("CollapseDelay",600);MoreCollapseDelayMs=store.GetInteger("MoreCollapse",1500);AutoHideMs=store.GetInteger("AutoHide",5000);CursorOffsetPx=store.GetInteger("Offset",5);IdleOpacity=store.GetInteger("IdleOpacity",42);ActiveOpacity=store.GetInteger("ActiveOpacity",100);CornerMarginPx=store.GetInteger("CornerMargin",90);foreach(var k in ActionCatalog.Kinds){var d=ActionCatalog.Defaults(k);Preferences[k]=d.Select(x=>new ActionPreference(x.Id,true,false)).ToList();}try{var json=store.GetString("CustomActions","[]");CustomActions.AddRange(JsonSerializer.Deserialize<List<ContextAction>>(json)??new());}catch{}}
 public void Save(){store.SetBool("Enabled",Enabled);store.SetBool("Auto",AutomaticPrioritization);store.SetInteger("Primary",PrimaryCount);store.SetEnumValue("Ux",UxMode);store.SetEnumValue("Position",PositionMode);store.SetInteger("SelectionDelay",SelectionDelayMs);store.SetInteger("HoverDelay",HoverDelayMs);store.SetInteger("CollapseDelay",CollapseDelayMs);store.SetInteger("MoreCollapse",MoreCollapseDelayMs);store.SetInteger("AutoHide",AutoHideMs);store.SetInteger("Offset",CursorOffsetPx);store.SetInteger("IdleOpacity",IdleOpacity);store.SetInteger("ActiveOpacity",ActiveOpacity);store.SetInteger("CornerMargin",CornerMarginPx);store.SetString("CustomActions",JsonSerializer.Serialize(CustomActions));}
 internal IReadOnlyList<ContextAction> Order(SelectionKind k,List<ContextAction>a){if(!Preferences.TryGetValue(k,out var p))return a;var map=p.Select((x,i)=>new{x.Id,x.Enabled,x.Favorite,I=i}).ToDictionary(x=>x.Id);return a.Where(x=>!map.ContainsKey(x.Id)||map[x.Id].Enabled).OrderByDescending(x=>map.TryGetValue(x.Id,out var m)&&m.Favorite).ThenByDescending(x=>AutomaticPrioritization&&Usage.TryGetValue(x.Id,out var u)?u.Count:0).ThenBy(x=>map.TryGetValue(x.Id,out var m)?m.I:int.MaxValue).ToList();}
 public bool IsFavorite(SelectionKind k,string id)=>Preferences.TryGetValue(k,out var p)&&p.Any(x=>x.Id==id&&x.Favorite);public long UsageCount(string id)=>Usage.TryGetValue(id,out var u)?u.Count:0;public void RecordUsage(string id){var n=DateTime.UtcNow;Usage[id]=Usage.TryGetValue(id,out var u)?u with{Count=u.Count+1,LastUsedUtc=n}:new(id,1,n);Save();}
 public void Export(string path){var c=new UserConfig(1,Preferences.ToDictionary(x=>x.Key.ToString(),x=>x.Value),CustomActions.ToList(),PositionMode,UxMode,PrimaryCount,CornerMarginPx);File.WriteAllText(path,JsonSerializer.Serialize(c,new JsonSerializerOptions{WriteIndented=true}));}
 public void Import(string path){var c=JsonSerializer.Deserialize<UserConfig>(File.ReadAllText(path))??throw new InvalidDataException("Ungültige Konfiguration");CustomActions.Clear();CustomActions.AddRange(c.CustomActions);PositionMode=c.PositionMode;UxMode=c.UxMode;PrimaryCount=c.PrimaryCount;CornerMarginPx=c.CornerMarginPx;foreach(var x in c.Preferences)if(Enum.TryParse<SelectionKind>(x.Key,out var k))Preferences[k]=x.Value;Save();}
}
